/* utilities */
async function getCommuneNameFromInseeCode(inseeCode) {
    const base = "https://www.insee.fr/fr/metadonnees/geographie/commune/";
    const response = await fetch(base+inseeCode);
    if (!response.ok) throw new Error("Invalid INSEE code or unreachable site");
    const html = await response.text();
    const match = html.match(/<title>([^<]+) - Commune \d{5} \| INSEE<\/title>/);
    if (match && match[1]) {
        return match[1].trim();
    }
    throw new Error("Commune name not found");
}
async function getCommuneInfo(inseeCode) {
    const url = `https://geo.api.gouv.fr/communes/${inseeCode}?fields=nom,centre,mairie&geometry=mairie`;
    const response = await fetch(url);
    if (!response.ok) throw new Error("Invalid INSEE code or API error");
    const data = await response.json();
    return {
        name: data.nom,
        mairieCoordinates: data.geometry ? data.geometry.coordinates : null
    };
}


/* matching insee codes including bi-name stations */
function matchInsee(f, g){
    let ginsee = g.Insee||"KK";
    if(ginsee === f.insee || (f.inse2 && ginsee === f.inse2) || (f.inse3 && ginsee === f.inse3)) return true;
    return false && console.log(`check insee code ${ginsee} :: ${f.insee}`);
}
function matchMinInsee(f, g){
    let ginsee = g.Insee.slice(0,2);
    if(ginsee === f.insee.slice(0,2) || (f.inse2 && ginsee === f.inse2.slice(0,2))) return true;
    return false;
}

function slugifyTopo(str) {
    if (!str) return '';
    return str.toLowerCase()
        .normalize('NFD')
        .replace(/[\u0300-\u036f]/g, '')    // remove diacritics
        .replace(/œ/g, 'oe')                // replace œ ligature and...
        .replace(/ß/g, 'ss').replace(/æ/g, 'ae').replace(/ĳ/g, 'ij')
        .replace(/[^a-z0-9\s]/g, ' ')       // remove non-alpha/digit chars
        .replace(/\s+/g, ' ').trim();       // single inner whitespaces
}

/* counting similar gare-nymes both ways */
function matchGare(f, g){
    const matchRight = (fnym, gnym) => fnym === gnym;
	const matchArticle = (fnym) => {
		const articles = ["L'","La ","Le ","Les "];
		let atl = articles.find(a => fnym.startsWith(a));
        return atl ? fnym.split(atl)[1].trim() : fnym;
	};
    const noDiacritx = (str) => str.normalize('NFD').replace(/[\u0300-\u036f]/g, '');
    const normalSlug = (str) => str ? noDiacritx(str).replace(' - ','-') : str;
	const articlesF = ["L'","La ","Le ","Les "];
    const articleOffF = (str) => str.replace(articlesF.find(a => str.startsWith(a)),"").trim();
	const articlesG = [" (L')"," (La)"," (Le)"," (Les)"];
    const articleOffG = (str) => str.replace(articlesG.find(a => str.includes(a)),"").trim();
    //<run>
    if(!g.Gare || !f.alt) return false;
    if( f.alt.some(fnym => matchRight(fnym, g.Gare)) ) return true;
    let gnym0 = g.Gare;
    if(gnym0.includes(" (L")){
        gnym0 = slugifyTopo(articleOffG(g.Gare)); //removes everything after " (L..."
        if( f.alt.some(fnym => matchRight(slugifyTopo(articleOffF(fnym)), gnym0))) return true;
    } else {
        gnym0 = slugifyTopo(g.Gare);
        if( f.alt.some(fnym => matchRight(slugifyTopo(fnym), gnym0))) return true;
    }
    return false;
}
function fullMatch(f, g, toCheck){
    const expandAlt = (f, g) => ([...new Set(f.alt.concat([g.Gare]))]);
    const combiGF = (f, g) => ({"id":[f.id,g.Num], "alt":expandAlt(f,g), "cie":f.cie, "nom":[f.nom,f.commu,g.Commune], "cc":[f.insee,g.Insee]});
    if(!f.insee || !g.Insee) return false;
    if(matchInsee(f, g) && matchGare(f, g)) return true;
    if(matchMinInsee(f, g) && matchGare(f, g))
        return void toCheck.push(combiGF(f, g));
}

function combineObjects(objs) {
  const combined = {};
  const keys = new Set();
  // Collect all keys in all objects
  objs.forEach(obj => {
    Object.keys(obj).forEach(k => keys.add(k));
  });

  keys.forEach(key => {
    // Collect all distinct values for this key
    const values = objs
      .map(o => o[key])
      .filter(v => v !== undefined && v !== null);
    const uniqueValues = [...new Set(values)];

    if(uniqueValues.length === 0) {
      combined[key] = undefined;
    } else if (uniqueValues.length === 1) {
      combined[key] = uniqueValues[0];
    } else {
      // Concatenate distinct values as strings, separated by comma
      combined[key] = uniqueValues;
    }
  });

  return combined;
}

function cumulate(acc, f, base){
    const fixInseeBug = (g) => void (g.Insee = g.Insee?.length === 4 ? "0"+g.Insee : g.Insee) || g;
	const addingboth = (f, g) => {
		f.Num = g.Num;
		f.cie = f.cie||g.Cie;
		if(!f.alt.includes(g.Gare)) f.alt.push(g.Gare);
        return (delete f.a) && (delete f.gare) && (delete f.cc) && f;
	};
    const lightF = ({alt, nom, insee, ...rest}) => ({alt, nom, insee});
    if(!f.alt) throw Error(`no alt array in: ${JSON.stringify(f)}`);
    if(!f.insee) return acc;
    let newbase = base.map(g => fixInseeBug(g)); // fixing bug in XLS transfer
    let resArr = newbase.filter(g => fullMatch(f, g, acc[2]));
	if(resArr.length === 0) {acc[1].push(lightF(f)); return acc}
	if(resArr.length > 2) console.log(`aï mundo  [ ${resArr.length} ] ${JSON.stringify(combineObjects(resArr))}`);
	const gg = resArr[0]; // TODO index depending on Cie ...
    acc[0].push(addingboth(f, gg));
	return acc;
}

function sortByCieNom(ff, prop1, prop2){
    const getSortCode = (a, b, prop) => a[prop].localeCompare(b[prop]);
    const getSortCod2 = (a, b, prop) => a[prop][0].localeCompare(b[prop][0]);
    return ff.sort((a, b) => {
  // First sort by "Co" (string property)
            const sortCode = getSortCode(a,b,prop1); //a.cie.localeCompare(b.cie);
            if (sortCode !== 0) return sortCode;
  // If "Co" values are identical, sort by "Id" (also string)
            return getSortCod2(a,b,prop2); //a.gare.localeCompare(b.gare);
        });
}


