function extractCie(ff, cieName, numLine){
    const fillFeature = (f, tmp) => {tmp.properties.id = f.Gare; tmp.properties.nom = f.Commune; tmp.properties.cc = f.Insee; return tmp};
    console.log(`Compagnie ${numLine}: ${cieName}`);
    const temp = {"properties":{"num":numLine,"pk":22,"use":"N","id":"_","nom":"_","cc":"_"},"type":"Feature","geometry":{"type":"Point","coordinates":[888888]}};
    const gList = ff
		.filter(f => f.Cie === cieName)
		.sort((a,b) => a.Commune.localeCompare(b.Commune))
		.map(f => JSON.stringify(fillFeature(f, temp)));
	return gList.join(',\n');
//    gList.forEach(f => console.log(JSON.stringify(fillFeature(f, temp))+","));
//    return 'extractCie';
}
async function processFiles(fileWerma, fileXLS36) {
    try {
        const rawWerma = await fa.readFile(fileWerma, 'utf-8');
        const werma = JSON.parse(rawWerma).A;
        const rawXLSv36 = await fa.readFile(fileXLS36, 'utf-8');
        const xls36 = JSON.parse(rawXLSv36).gXLSv36;

    //////extractCie(xls36, CIENAME, SHORT);    if(xls36) return;

        let newA = werma.reduce((acc, f) => cumulate(acc, f, xls36), [[], [], []]);
        console.log(`gWermaFF ok = ${newA[0].length} / ${werma.length} / ${xls36.length}`);
        console.log(`gWermaFF missing = ${newA[1].length} / `);
        console.log(`.of whom toCheck = ${newA[2].length} / `);
    //saveSync( JSON.stringify(newA[1]), "gWERMAmissing.json");
        const checkable = sortByCieNom(newA[2], "cie", "alt");
        saveSync( JSON.stringify(checkable), "gares2check.json");
    } catch (err) {
        console.error('Error processing files:', err);
    }
}

async function extractByCie(fileXLS36, cieName, numLine) {
    try {
        const rawXLSv36 = await fa.readFile(fileXLS36, 'utf-8');
        const xls36 = JSON.parse(rawXLSv36).gXLSv36;
//        saveSync( JSON.stringify(checkable), "gares2check.json");
		saveSync(extractCie(xls36, cieName, numLine), numLine+".json");
    } catch (err) {
        console.error('Error extractByCie:', err);
    }
}

